begin;
create extension if not exists pgtap with schema extensions;
select plan(5);
insert into auth.users(id) select ('62000000-0000-0000-0000-00000000000'||n)::uuid from generate_series(1,2) n;
insert into auth.sessions(id,user_id,created_at,updated_at) select ('72000000-0000-0000-0000-00000000000'||n)::uuid,('62000000-0000-0000-0000-00000000000'||n)::uuid,now(),now() from generate_series(1,2) n;
insert into public.employees(id,employee_code,display_name,role) select ('82000000-0000-0000-0000-00000000000'||n)::uuid,'EXP'||n,'Synthetic','employee' from generate_series(1,2) n;
insert into private.employee_auth(employee_id,auth_user_id) select ('82000000-0000-0000-0000-00000000000'||n)::uuid,('62000000-0000-0000-0000-00000000000'||n)::uuid from generate_series(1,2) n;
insert into public.employee_permissions(employee_id,cases_read,cases_write) values ('82000000-0000-0000-0000-000000000001',true,true),('82000000-0000-0000-0000-000000000002',true,false);
insert into public.families(id,name,phone) values ('93000000-0000-0000-0000-000000000001','أسرة اختبار الانتهاء','01012345678');
select has_column('public','families','national_id_expires_on','family stores the ID expiry date');
select set_config('request.jwt.claims','{"sub":"62000000-0000-0000-0000-000000000001","session_id":"72000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$update public.families set national_id_expires_on='2027-01-15' where id='93000000-0000-0000-0000-000000000001'$$,'writer can save a future expiry date');
select is((select national_id_expires_on from public.families where id='93000000-0000-0000-0000-000000000001'),'2027-01-15'::date,'future expiry date is saved');
select lives_ok($$update public.families set national_id_expires_on='2020-01-15' where id='93000000-0000-0000-0000-000000000001'$$,'past expiry dates can be recorded');
reset role;
select set_config('request.jwt.claims','{"sub":"62000000-0000-0000-0000-000000000002","session_id":"72000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select national_id_expires_on from public.families where id='93000000-0000-0000-0000-000000000001'),'2020-01-15'::date,'reader sees expiry date for alerting');
select * from finish();
rollback;
